// Per-language slices of the translation bundles (see slice.ts and vite.config.ts).
declare module '*?lang=en' { const d: Record<string, string>; export default d; }
declare module '*?lang=fr' { const d: Record<string, string>; export default d; }
declare module '*?lang=rw' { const d: Record<string, string>; export default d; }
declare module '*?lang=sw' { const d: Record<string, string>; export default d; }
